from app.tm1_templates import TM1TemplateFactory


class TemplateFactory(TMX1TemplateFactory):
    pass


class TM1TemplateFactory:
    """Lightweight template factory for starter TM1 generation."""

    @staticmethod
    def load_process_template(process_name: str = "LoadData") -> str:
        return f"""\
# TM1 process generated by starter orchestrator
# Process: {process_name}

# ----- Setup -----
SetInputFileName('input.csv');
SetOutputFileName('output.log');

# ----- Core logic -----
DataSourceType = 'ASCII';
DatasourceNameForServer = 'input.csv';
DatasourceNameForClient = 'input.csv';

# Replace with TM1-specific code for your target cube and source
# Example:
# IF( DimensionExists('Product') = 0 );
#   ExecuteProcess('CreateProductDimension');
# ENDIF;

# ----- Load data into target cube -----
# CubeLoadData('Sales');

"""

    @staticmethod
    def dimension_template(dimension_name: str) -> str:
        return f"""\
# TM1 dimension generation template
# Dimension: {dimension_name}

# Add dimension members and hierarchies here.
# Example:
# DimensionCreate('{dimension_name}');
# DimensionElementInsert('{dimension_name}', '', 'Total', 'N');
"""
